function validate([boxTypes, truckSize]) {
  if (!Array.isArray(boxTypes) || boxTypes.length < 1 || boxTypes.length > 1000) return 'boxTypes needs 1 to 1000 entries.';
  for (const pair of boxTypes) {
    if (!Array.isArray(pair) || pair.length !== 2) return 'Each box type is a pair [numberOfBoxes, numberOfUnitsPerBox].';
    if (pair.some(v => !Number.isInteger(v) || v < 1 || v > 1000)) return 'Box counts and units per box are between 1 and 1000.';
  }
  if (!Number.isInteger(truckSize) || truckSize < 1 || truckSize > 1000000) return 'truckSize is between 1 and 1000000.';
  return null;
}

