function maximumUnits(boxTypes, truckSize) {
  boxTypes.sort((a, b) => b[1] - a[1]);
  let space = truckSize;
  let units = 0;

  for (const [count, perBox] of boxTypes) {
    if (space === 0) {
      break;
    }
    const taken = Math.min(count, space);
    units += taken * perBox;
    space -= taken;
  }
  return units;
}

