function maximumUnits(boxTypes, truckSize) {
  // 0/1 knapsack over individual boxes: dp[c] = most units using at most c boxes.
  const boxes = [];
  for (const [count, perBox] of boxTypes) for (let i = 0; i < count; i++) boxes.push(perBox);
  const cap = Math.min(truckSize, boxes.length);
  const dp = new Array(cap + 1).fill(0);
  for (const value of boxes) for (let c = cap; c >= 1; c--) dp[c] = Math.max(dp[c], dp[c - 1] + value);
  return dp[cap];
}

