function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const boxTypes = Array.from({ length: 1000 }, () => [int(1, 1000), int(1, 1000)]);
    const truckSize = rand() < 0.5 ? int(1, 500000) : int(1, 1000000);
    return [boxTypes, truckSize];
  }
  const types = int(1, 6);
  const maxUnits = rand() < 0.2 ? 1000 : int(1, 10);
  const boxTypes = Array.from({ length: types }, () => [int(1, 5), int(1, maxUnits)]);
  return [boxTypes, int(1, 35)];
}
